    "sql": "CREATE OR REPLACE FUNCTION send_trade_offer_v2( p_receiver_id UUID, p_offer_pokemon JSONB, p_offer_items JSONB, p_offer_money BIGINT, p_request_pokemon JSONB, p_request_items JSONB, p_request_money BIGINT, p_message TEXT ) RETURNS UUID AS $$ DECLARE v_sender_id UUID; v_save JSONB; v_new_save JSONB; v_trade_id UUID; v_p_uid TEXT; item_key TEXT; item_val TEXT; item_qty INT; BEGIN v_sender_id := auth.uid(); IF v_sender_id IS NULL THEN RAISE EXCEPTION 'No autorizado.'; END IF; SELECT save_data INTO v_save FROM game_saves WHERE user_id = v_sender_id FOR UPDATE; v_new_save := v_save; IF p_offer_pokemon IS NOT NULL THEN v_p_uid := p_offer_pokemon->>'uid'; v_new_save := jsonb_set( v_new_save, '{team}', COALESCE((SELECT jsonb_agg(p) FROM jsonb_array_elements(v_save->'team') p WHERE p->>'uid' != v_p_uid), '[]'::jsonb) ); IF jsonb_array_length(v_new_save->'team') = jsonb_array_length(v_save->'team') THEN v_new_save := jsonb_set( v_new_save, '{box}', COALESCE((SELECT jsonb_agg(p) FROM jsonb_array_elements(v_save->'box') p WHERE p->>'uid' != v_p_uid), '[]'::jsonb) ); IF jsonb_array_length(v_new_save->'box') = jsonb_array_length(v_save->'box') THEN RAISE EXCEPTION 'Pokémon no encontrado en tu inventario.'; END IF; END IF; END IF; IF (v_new_save->>'money')::BIGINT < p_offer_money THEN RAISE EXCEPTION 'Dinero insuficiente.'; END IF; v_new_save := jsonb_set(v_new_save, '{money}', to_jsonb((v_new_save->>'money')::BIGINT - p_offer_money)); IF p_offer_items IS NOT NULL AND p_offer_items != '{}'::jsonb THEN FOR item_key, item_val IN SELECT * FROM jsonb_each_text(p_offer_items) LOOP item_qty := item_val::INT; IF item_qty > 0 THEN IF NOT (v_new_save->'inventory' ? item_key) OR (v_new_save->'inventory'->>item_key)::INT < item_qty THEN RAISE EXCEPTION 'Item insuficiente: %', item_key; END IF; IF (v_new_save->'inventory'->>item_key)::INT - item_qty <= 0 THEN v_new_save := jsonb_set( v_new_save, '{inventory}', (v_new_save->'inventory') - item_key ); ELSE v_new_save := jsonb_set( v_new_save, ARRAY['inventory', item_key], to_jsonb((v_new_save->'inventory'->>item_key)::INT - item_qty) ); END IF; END IF; END LOOP; END IF; UPDATE game_saves SET save_data = v_new_save, last_save_id = gen_random_uuid(), updated_at = NOW() WHERE user_id = v_sender_id; INSERT INTO trade_offers ( sender_id, receiver_id, offer_pokemon, offer_items, offer_money, request_pokemon, request_items, request_money, message, status ) VALUES ( v_sender_id, p_receiver_id, p_offer_pokemon, p_offer_items, p_offer_money, p_request_pokemon, p_request_items, p_request_money, p_message, 'pending' ) RETURNING id INTO v_trade_id; RETURN v_trade_id; END; $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog; CREATE OR REPLACE FUNCTION accept_trade_v2( p_trade_id UUID ) RETURNS BOOLEAN AS $$ DECLARE v_trade RECORD; v_caller_id UUID; v_receiver_save JSONB; v_new_receiver_save JSONB; v_r_uid TEXT; item_key TEXT; item_val TEXT; item_qty INT; BEGIN v_caller_id := auth.uid(); SELECT * INTO v_trade FROM trade_offers WHERE id = p_trade_id FOR UPDATE; IF NOT FOUND OR v_trade.status != 'pending' THEN RAISE EXCEPTION 'Oferta no válida o ya procesada.'; END IF; IF v_trade.receiver_id != v_caller_id THEN RAISE EXCEPTION 'No autorizado.'; END IF; SELECT save_data INTO v_receiver_save FROM game_saves WHERE user_id = v_caller_id FOR UPDATE; v_new_receiver_save := v_receiver_save; IF v_trade.request_pokemon IS NOT NULL THEN v_r_uid := v_trade.request_pokemon->>'uid'; v_new_receiver_save := jsonb_set( v_new_receiver_save, '{team}', COALESCE((SELECT jsonb_agg(p) FROM jsonb_array_elements(v_receiver_save->'team') p WHERE p->>'uid' != v_r_uid), '[]'::jsonb) ); IF jsonb_array_length(v_new_receiver_save->'team') = jsonb_array_length(v_receiver_save->'team') THEN v_new_receiver_save := jsonb_set( v_new_receiver_save, '{box}', COALESCE((SELECT jsonb_agg(p) FROM jsonb_array_elements(v_receiver_save->'box') p WHERE p->>'uid' != v_r_uid), '[]'::jsonb) ); END IF; END IF; IF (v_new_receiver_save->>'money')::BIGINT < v_trade.request_money THEN RAISE EXCEPTION 'Dinero insuficiente para aceptar el intercambio.'; END IF; v_new_receiver_save := jsonb_set(v_new_receiver_save, '{money}', to_jsonb((v_new_receiver_save->>'money')::BIGINT - v_trade.request_money)); IF v_trade.request_items IS NOT NULL AND v_trade.request_items != '{}'::jsonb THEN FOR item_key, item_val IN SELECT * FROM jsonb_each_text(v_trade.request_items) LOOP item_qty := item_val::INT; IF item_qty > 0 THEN IF NOT (v_new_receiver_save->'inventory' ? item_key) OR (v_new_receiver_save->'inventory'->>item_key)::INT < item_qty THEN RAISE EXCEPTION 'Item insuficiente para cumplir el intercambio: %', item_key; END IF; IF (v_new_receiver_save->'inventory'->>item_key)::INT - item_qty <= 0 THEN v_new_receiver_save := jsonb_set( v_new_receiver_save, '{inventory}', (v_new_receiver_save->'inventory') - item_key ); ELSE v_new_receiver_save := jsonb_set( v_new_receiver_save, ARRAY['inventory', item_key], to_jsonb((v_new_receiver_save->'inventory'->>item_key)::INT - item_qty) ); END IF; END IF; END LOOP; END IF; UPDATE game_saves SET save_data = v_new_receiver_save, last_save_id = gen_random_uuid(), updated_at = NOW() WHERE user_id = v_caller_id; IF v_trade.offer_pokemon IS NOT NULL THEN INSERT INTO claim_queue (user_id, source_type, source_id, asset_data) VALUES (v_caller_id, 'trade', p_trade_id, jsonb_build_object('type', 'pokemon', 'data', v_trade.offer_pokemon)); END IF; IF v_trade.offer_money > 0 THEN INSERT INTO claim_queue (user_id, source_type, source_id, asset_data) VALUES (v_caller_id, 'trade', p_trade_id, jsonb_build_object('type', 'money', 'data', v_trade.offer_money)); END IF; IF v_trade.offer_items IS NOT NULL AND v_trade.offer_items != '{}'::jsonb THEN FOR item_key, item_val IN SELECT * FROM jsonb_each_text(v_trade.offer_items) LOOP item_qty := item_val::INT; IF item_qty > 0 THEN INSERT INTO claim_queue (user_id, source_type, source_id, asset_data) VALUES (v_caller_id, 'trade', p_trade_id, jsonb_build_object('type', 'item', 'data', jsonb_build_object('name', item_key, 'qty', item_qty))); END IF; END LOOP; END IF; IF v_trade.request_pokemon IS NOT NULL THEN INSERT INTO claim_queue (user_id, source_type, source_id, asset_data) VALUES (v_trade.sender_id, 'trade', p_trade_id, jsonb_build_object('type', 'pokemon', 'data', v_trade.request_pokemon)); END IF; IF v_trade.request_money > 0 THEN INSERT INTO claim_queue (user_id, source_type, source_id, asset_data) VALUES (v_trade.sender_id, 'trade', p_trade_id, jsonb_build_object('type', 'money', 'data', v_trade.request_money)); END IF; IF v_trade.request_items IS NOT NULL AND v_trade.request_items != '{}'::jsonb THEN FOR item_key, item_val IN SELECT * FROM jsonb_each_text(v_trade.request_items) LOOP item_qty := item_val::INT; IF item_qty > 0 THEN INSERT INTO claim_queue (user_id, source_type, source_id, asset_data) VALUES (v_trade.sender_id, 'trade', p_trade_id, jsonb_build_object('type', 'item', 'data', jsonb_build_object('name', item_key, 'qty', item_qty))); END IF; END LOOP; END IF; UPDATE trade_offers SET status = 'accepted', updated_at = NOW() WHERE id = p_trade_id; RETURN TRUE; END; $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog; REVOKE EXECUTE ON FUNCTION public.send_trade_offer_v2(uuid, jsonb, jsonb, bigint, jsonb, jsonb, bigint, text) FROM PUBLIC, anon; GRANT EXECUTE ON FUNCTION public.send_trade_offer_v2(uuid, jsonb, jsonb, bigint, jsonb, jsonb, bigint, text) TO authenticated, service_role; REVOKE EXECUTE ON FUNCTION public.accept_trade_v2(uuid) FROM PUBLIC, anon; GRANT EXECUTE ON FUNCTION public.accept_trade_v2(uuid) TO authenticated, service_role; INSERT INTO public.system_config (key, value) VALUES ('db_version', '20260520000000'::jsonb) ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = NOW();",
